const raw = $json;
let chatId = '';
let text = '';
let verifiedPhone = '';
let hasAttachment = false;
let attachmentUnsupported = false;
let attachmentMimeType = '';
let messageId = '';

let msg = null;
let cbData = null;
try {
  const trig = $('Telegram Trigger').item.json;
  if (trig.callback_query) {
    cbData = trig.callback_query.data || '';
    msg = trig.callback_query.message || null;
  } else {
    msg = trig.message || null;
  }
} catch (e) {
  msg = null;
}

if (msg) {
  chatId = String((msg.chat || {}).id || '');
  if (cbData !== null) {
    text = cbData;
  } else {
    messageId = String(msg.message_id || '');
    const rawText = msg.text || msg.caption || '';
    const contact = msg.contact;
    if (contact && contact.phone_number && String(contact.user_id) === String((msg.from || {}).id)) {
      verifiedPhone = String(contact.phone_number).replace(/[^0-9]/g, '');
    }
    let mime = '';
    try { mime = $('Get Attachment Info').item.json.attachmentMimeType || ''; } catch (e) {}
    if (mime) {
      hasAttachment = true;
      attachmentMimeType = mime;
      const supported = mime === 'application/pdf' || mime.indexOf('image/') === 0;
      if (supported) {
        text = (rawText ? rawText + '\n' : '') + '[مرفق سيرة ذاتية بصيغة ' + mime + ']';
      } else {
        attachmentUnsupported = true;
        text = '[صيغة غير مدعومة: ' + mime + ']';
      }
    } else {
      text = rawText;
    }
  }
} else {
  chatId = String(raw.chatId || '');
  text = raw.text || '';
  verifiedPhone = raw.verifiedPhone || '';
}

const out = { json: { chatId, text, verifiedPhone, hasAttachment, attachmentUnsupported, attachmentMimeType, messageId } };
if ($input.item.binary && $input.item.binary.data) {
  out.binary = { data: $input.item.binary.data };
}
return out;

const msg = $json.message || {};
let fileId = '';
let mimeType = '';
if (msg.document) {
  fileId = msg.document.file_id;
  mimeType = msg.document.mime_type || 'application/octet-stream';
} else if (msg.photo && msg.photo.length) {
  fileId = msg.photo[msg.photo.length - 1].file_id;
  mimeType = 'image/jpeg';
}
return { json: { ...$json, attachmentFileId: fileId, attachmentMimeType: mimeType } };

const norm = $('Normalize Input').item.json;
const sess = $json;
const storedPhone = (sess && sess.verifiedPhone) ? String(sess.verifiedPhone) : '';
const effectiveVerifiedPhone = norm.verifiedPhone || storedPhone;
const out = { json: {
  ...norm,
  effectiveVerifiedPhone,
  step: sess.step || '',
  cvText: sess.cvText || '',
  customerName: sess.customerName || '',
  email: sess.email || '',
  fieldOfWork: sess.fieldOfWork || '',
  preferredLocation: sess.preferredLocation || '',
  jobTitlesCsv: sess.jobTitlesCsv || '',
  interviewJobTitle: sess.interviewJobTitle || '',
  interviewCompany: sess.interviewCompany || '',
  interviewDate: sess.interviewDate || '',
  contactCategory: sess.contactCategory || '',
  contactMessageText: sess.contactMessageText || ''
} };
if (norm.hasAttachment) {
  try {
    const bin = $('Normalize Input').item.binary;
    if (bin && bin.data) out.binary = { data: bin.data };
  } catch (e) {}
}
return out;

const merged = $('Merge Verification State').item.json;
const approval = $json;
const isApproved = !!(approval && approval.whatsappNumber);
let computedStartDate = null;
let computedEndDate = null;
if (isApproved) {
  const durationDays = approval.subscriptionDurationDays || 0;
  let start;
  if (approval.startMode === 'fixed' && approval.fixedStartDate) {
    start = new Date(approval.fixedStartDate + 'T00:00:00Z');
    if (isNaN(start.getTime())) start = new Date();
  } else {
    start = new Date();
  }
  const end = new Date(start.getTime() + durationDays * 24 * 60 * 60 * 1000);
  const toISODate = (d) => d.toISOString().slice(0, 10);
  computedStartDate = toISODate(start);
  computedEndDate = toISODate(end);
}
let existing = null;
try {
  const rows = $('Check Existing Customer').all();
  if (rows && rows.length > 0 && rows[0].json && rows[0].json.id) {
    existing = rows[0].json;
  }
} catch (e) {}
const customerState = existing ? (existing.subscriptionStatus === 'Active' ? 'active' : 'expired') : 'none';
const out = {
  json: {
    ...merged,
    isApproved,
    alreadyCustomer: customerState === 'active',
    customerState,
    existingId: existing ? existing.id : null,
    existingOnboardingStatus: existing ? (existing.onboardingStatus || '') : '',
    existingCustomerName: existing ? (existing.customerName || '') : '',
    existingEmail: existing ? (existing.email || '') : '',
    existingFieldOfWork: existing ? (existing.fieldOfWork || '') : '',
    existingCvText: existing ? (existing.cvText || '') : '',
    existingPreferredLocation: existing ? (existing.preferredLocation || '') : '',
    existingJobTitles: existing ? (existing.jobTitles || '') : '',
    approvedDurationDays: isApproved ? approval.subscriptionDurationDays : null,
    approvedMonthlyFee: isApproved ? approval.monthlyFee : null,
    computedStartDate,
    computedEndDate
  }
};
if (merged.hasAttachment) {
  try {
    const bin = $('Merge Verification State').item.binary;
    if (bin && bin.data) out.binary = { data: bin.data };
  } catch (e) {}
}
return out;

const v = $json;
const text = (v.text || '').trim();
const step = v.step || '';

const REGIONS = ['الرياض','مكة المكرمة','المدينة المنورة','القصيم','المنطقة الشرقية','عسير','تبوك','حائل','الحدود الشمالية','جازان','نجران','الباحة','الجوف'];
const FLEX = '🌐 مرن - أي مكان في المملكة';
const OTHER_CITY = '✏️ مدينة/منطقة أخرى (اكتبها)';
const CITY_OK = '✅ القائمة كافية، كمّل';
const CITY_ADD = '➕ أضف مدينة/منطقة ثانية';
const MAX_CITIES = 5;
const TITLES_OK = '✅ القائمة كافية، تقدّم بها';
const TITLES_ADD = '➕ أضف مجال آخر';
const TITLES_REMOVE = '🗑️ احذف مجال غير مناسب';
const MAX_FIELDS = 3;
const RENEW_OLD = '🔄 استمرار بنفس البيانات القديمة';
const RENEW_FRESH = '🆕 البدء من جديد بالكامل';
const CONFIRM_OLD = '✅ تأكيد والبدء بنفس البيانات';
const BACK_TO_FRESH = '🆕 لا، أفضل البدء من جديد';
const NUDGE = 'من فضلك اختر أحد الأزرار بالأسفل 👇 (وإذا ما تظهر لك الأزرار، اكتب رقم الخيار فقط)\n\n';
const REGION_HINT = ' (لو ما ظهرت لك الأزرار: اكتب رقم من 1 إلى 13 لاختيار منطقة، أو 14 للخيار المرن، أو 15 لكتابة مدينة/منطقة أخرى)';
const INTERVIEW_BTN = '🎉 جتني مقابلة!';
const STATUS_BTN = '📋 حالتي';
const CONTACT_BTN = '📞 تواصل معنا';
const CONTACT_COMPLAINT_BTN = '📝 ملاحظة أو شكوى';
const CONTACT_SUPPORT_BTN = '🎧 طلب دعم';
const CONTACT_HEART_BTN = '💌 رسالة من قلب لقلب';
const CHECK_STATUS_BTN = '🔄 تحقق من اشتراكي';

function titlesArr(csv) {
  return (csv || '').split(',').map(function(s){return s.trim();}).filter(Boolean);
}

function locationsArr(csv) {
  return (csv || '').split(',').map(function(s){return s.trim();}).filter(Boolean);
}

function buildTitlesMessage(csv) {
  const titles = titlesArr(csv);
  let msg = 'بناءً على سيرتك الذاتية، هذي أبرز ' + MAX_FIELDS + ' مجالات مهنية عريضة راح نقدّم عليها نيابةً عنك (وليست مسميات وظيفية دقيقة — هذا أشمل ويغطي كل الوظائف المناسبة داخل كل مجال):\n\n';
  titles.forEach(function(t, i){ msg += (i+1) + '. ' + t + '\n'; });
  msg += '\nاختر واحد: (1) القائمة كافية وأقدّم بها — (2) أضيف مجال آخر (بحد أقصى ' + MAX_FIELDS + ') — (3) احذف مجال غير مناسب، إما بالضغط على الزر أو بكتابة الرقم:';
  return msg;
}

function buildRemovePrompt(csv) {
  const titles = titlesArr(csv);
  let msg = 'اختر رقم المجال اللي تحب تحذفه من القائمة (اكتب الرقم بس مثلاً 2)، أو اكتب اسمه بالضبط:\n\n';
  titles.forEach(function(t, i){ msg += (i+1) + '. ' + t + '\n'; });
  return msg;
}

function buildCitiesMessage(csv) {
  const cities = locationsArr(csv);
  let msg = 'تمام ✅ هذي مدنك/مناطقك المفضلة حتى الآن:\n\n';
  cities.forEach(function(c, i){ msg += (i+1) + '. ' + c + '\n'; });
  msg += '\n(1) القائمة كافية، كمّل — (2) أضف مدينة/منطقة ثانية (بحد أقصى ' + MAX_CITIES + ')، إما بالضغط على الزر أو بكتابة الرقم:';
  return msg;
}

function buildOldDataSummary(v) {
  let msg = '📋 هذي بياناتك المحفوظة من قبل:\n\n';
  msg += '👤 الاسم: ' + (v.existingCustomerName || '-') + '\n';
  msg += '💼 المجال: ' + (v.existingFieldOfWork || '-') + '\n';
  msg += '📧 البريد: ' + (v.existingEmail || '-') + '\n';
  msg += '📍 المدن/المناطق المفضلة: ' + (v.existingPreferredLocation || '-') + '\n';
  msg += '🎯 المجالات المهنية: ' + (v.existingJobTitles || '-') + '\n\n';
  msg += '📄 السيرة الذاتية المحفوظة:\n' + (v.existingCvText || '-') + '\n\n';
  msg += 'تأكد من صحة البيانات أعلاه، واختر (1) للاستمرار بنفس البيانات أو (2) للبدء من جديد:';
  return msg;
}

let route = 'ignore';
let replyText = '';
let markPotential = false;
let patch = {
  chatId: v.chatId,
  verifiedPhone: v.effectiveVerifiedPhone || '',
  step,
  cvText: v.cvText || '',
  customerName: v.customerName || '',
  email: v.email || '',
  fieldOfWork: v.fieldOfWork || '',
  preferredLocation: v.preferredLocation || '',
  jobTitlesCsv: v.jobTitlesCsv || '',
  interviewJobTitle: v.interviewJobTitle || '',
  interviewCompany: v.interviewCompany || '',
  interviewDate: v.interviewDate || '',
  contactCategory: v.contactCategory || '',
  contactMessageText: v.contactMessageText || ''
};

if (v.customerState === 'active' && v.existingOnboardingStatus === 'AskedLanguage') {
  const rawText = text.toLowerCase();
  const arabicWords = ['عربي', 'العربية', 'ar'];
  const englishWords = ['english', 'انجليزي', 'إنجليزي', 'en'];
  let lang = '';
  if (arabicWords.some(function(w){ return rawText.indexOf(w) !== -1; })) lang = 'Arabic';
  else if (englishWords.some(function(w){ return rawText.indexOf(w) !== -1; })) lang = 'English';
  if (lang) {
    route = 'build_cv';
    patch.cvLanguageChoice = lang;
  } else {
    route = 'plain';
    replyText = 'من فضلك اختر لغة سيرتك الذاتية بالرد بكلمة واحدة: "عربي" أو "English"';
  }
} else if (v.customerState === 'active') {
  if (text === INTERVIEW_BTN) {
    patch.step = 'awaiting_interview_title';
    route = 'plain';
    replyText = 'الله يبارك لك ويوفقك 🤍 هذا خبر يفرحنا فعلاً!\n\nعشان نجهز لك خطة كاملة، ودّنا نعرف:\n📌 ما المسمى الوظيفي؟';
  } else if (text === STATUS_BTN) {
    route = 'check_status';
    replyText = '';
  } else if (text === CONTACT_BTN) {
    patch.step = 'awaiting_contact_type';
    route = 'contact_menu_kb';
    replyText = 'اختر نوع الرسالة اللي تحب ترسلها لفريق مسار:';
  } else if (step === 'awaiting_interview_title') {
    if (text) {
      patch.interviewJobTitle = text;
      patch.step = 'awaiting_interview_company';
      route = 'plain';
      replyText = 'تمام 👍 أي شركة؟';
    } else {
      route = 'plain';
      replyText = 'اكتب المسمى الوظيفي للوظيفة اللي جاتك فيها المقابلة:';
    }
  } else if (step === 'awaiting_interview_company') {
    if (text) {
      patch.interviewCompany = text;
      patch.step = 'awaiting_interview_date';
      route = 'plain';
      replyText = 'تمام، ومتى موعد المقابلة؟ (التاريخ والوقت إن أمكن)';
    } else {
      route = 'plain';
      replyText = 'اكتب اسم الشركة:';
    }
  } else if (step === 'awaiting_interview_date') {
    if (text) {
      patch.interviewDate = text;
      patch.step = '';
      route = 'prep_interview';
      replyText = '🌱 جهّز نفسك، نجهز لك الآن خطة كاملة للمقابلة بإذن الله، تحمّل شوي...';
    } else {
      route = 'plain';
      replyText = 'اكتب موعد المقابلة (التاريخ والوقت):';
    }
  } else if (step === 'awaiting_contact_type') {
    if (text === CONTACT_COMPLAINT_BTN || text === '1') {
      patch.contactCategory = 'complaint';
      patch.step = 'awaiting_contact_message';
      route = 'plain';
      replyText = 'اكتب ملاحظتك أو شكواك بخصوص الخدمة بكل صراحة، وبنطّلع عليها فورًا:';
    } else if (text === CONTACT_SUPPORT_BTN || text === '2') {
      patch.contactCategory = 'support';
      patch.step = 'awaiting_contact_message';
      route = 'plain';
      replyText = 'اكتب طلبك أو المشكلة اللي تواجهك، ونساعدك فيها بأقرب وقت:';
    } else if (text === CONTACT_HEART_BTN || text === '3') {
      patch.contactCategory = 'heart';
      patch.step = 'awaiting_contact_message';
      route = 'plain';
      replyText = 'هذي مساحة حرة لك 🤍 اكتب أي شي في بالك تجاه فريق مسار — رأيك، اقتراح، دعوة، كلمة شكر، أو حتى انتقاد صريح. كل كلمة توصلنا وتهمنا:';
    } else {
      route = 'contact_menu_kb';
      replyText = NUDGE + 'اختر نوع الرسالة اللي تحب ترسلها لفريق مسار:';
    }
  } else if (step === 'awaiting_contact_message') {
    if (text) {
      patch.contactMessageText = text;
      patch.step = '';
      route = 'send_contact_message';
      replyText = '';
    } else {
      route = 'plain';
      replyText = 'اكتب رسالتك:';
    }
  } else {
    route = 'active_menu_kb';
    replyText = 'وصلتنا رسالتك 🙏 حاليًا التواصل يكون فقط عن طريق الأزرار بالأسفل 👇 اختر اللي يناسبك، أو اضغط "📞 تواصل معنا" لإرسال رسالتك لفريق مسار:';
  }
} else if (v.customerState === 'expired' && !v.isApproved) {
  route = 'plain';
  replyText = '🌟 يا هلا فيك من جديد' + (v.existingCustomerName ? ' يا ' + v.existingCustomerName : '') + '! لاحظنا إن اشتراكك السابق انتهى.\n\nتحب تجدد اشتراكك وترجع تستفيد من الخدمة؟ تواصل معنا عبر واتساب على: +966544161255';
} else if (v.customerState === 'expired' && v.isApproved && !step) {
  route = 'renewal_choice_kb';
  replyText = '🎉 تم تجديد اشتراكك' + (v.existingCustomerName ? ' يا ' + v.existingCustomerName : '') + '، الله يوفقك!\n\nتحب نكمل بنفس سيرتك الذاتية وبياناتك السابقة، أو تفضّل تبدأ من جديد بالكامل (سيرة ذاتية جديدة وتفضيلات جديدة)؟ (1) استمرار بنفس البيانات — (2) البدء من جديد';
  patch.step = 'ask_renewal_choice';
} else if (step === 'ask_renewal_choice') {
  if (text === RENEW_OLD || text === '1') {
    patch.step = 'confirm_old_data';
    route = 'confirm_old_kb';
    replyText = buildOldDataSummary(v);
  } else if (text === RENEW_FRESH || text === '2') {
    patch.step = 'awaiting_cv';
    route = 'plain';
    replyText = 'تمام 👍 أرسل الآن سيرتك الذاتية الجديدة — ملف PDF أو صورة واضحة لها:';
  } else {
    route = 'renewal_choice_kb';
    replyText = NUDGE + '🎉 تم تجديد اشتراكك' + (v.existingCustomerName ? ' يا ' + v.existingCustomerName : '') + '، الله يوفقك!\n\n(1) استمرار بنفس البيانات — (2) البدء من جديد بالكامل';
  }
} else if (step === 'confirm_old_data') {
  if (text === CONFIRM_OLD || text === '1') {
    route = 'finalize_renewal';
  } else if (text === BACK_TO_FRESH || text === '2') {
    patch.step = 'awaiting_cv';
    route = 'plain';
    replyText = 'تمام 👍 أرسل الآن سيرتك الذاتية الجديدة — ملف PDF أو صورة واضحة لها:';
  } else {
    route = 'confirm_old_kb';
    replyText = NUDGE + buildOldDataSummary(v);
  }
} else if (!v.isApproved) {
  if (!v.effectiveVerifiedPhone) {
    route = 'need_phone';
    replyText = '🌱 "وَأَن لَّيْسَ لِلْإِنسَانِ إِلَّا مَا سَعَىٰ"\n\nكل خطوة تخطوها بحثًا عن رزقك هي خطوة مباركة، وما من مجتهد إلا وله نصيب. امنح نفسك اليوم فرصة المحاولة، فالسعي عبادة والرزق بيد الله.\n\nأهلاً وسهلاً 👋 أنا مسار، وجهتنا معك واحدة: نبحث ونقدّم نيابةً عنك بكل صدق واهتمام حتى تصل لوظيفة تليق فيك بإذن الله.\n\nاضغط الزر بالأسفل لمشاركة رقم جوالك ونبدأ معك:';
  } else if (text === CHECK_STATUS_BTN) {
    route = 'ignore';
    replyText = '';
  } else {
    route = 'pitch_status_kb';
    markPotential = true;
    replyText = 'فرصتك الحقيقية ما زالت قدّامك 🌟\n\nمب بس اللي بدون وظيفة يستاهل يبدأ من جديد — حتى إذا كنت شغّال الحين، تستاهل توظيف أفضل: مسمى أعلى، وضع يناسب مجهودك، بيئة تشوف فيها نفسك أكبر. واللي يوقفك مب نقص خبرتك، غالبًا هو الوقت والجهد اللي يحتاجه البحث الصحيح.\n\nهنا وين يجي دور "مسار".\n\nما نرسل سيرتك "نسخة واحدة" لعشرات الوظائف زي الطريقة المعتادة. كل وظيفة نتقدّم عليها نيابةً عنك، نعيد بناء سيرتك من الصفر خصيصًا لها — نبرز المهارات والكلمات المفتاحية اللي تطلبها هذي الوظيفة بالذات، عشان تعدّي أنظمة الفرز الآلي (ATS) وتوصل فعليًا لعين المسؤول، مو تنطفي بين مئات الطلبات المتشابهة. كل تقديم عندنا معاملة "فرصة وحيدة"، مو رسالة نكررها.\n\nوما نوقف عند التقديم بس. نراقب السوق باستمرار في تخصصك والوظائف اللي تستهدفها، ونطلع لك بالضبط وش ينقصك — شهادة، مهارة، أو حتى كلمة بسيرتك — عشان ترفع فرصك الحقيقية بدل ما تدور بعشوائية.\n\nوإذا وصلتك دعوة مقابلة، ما نسيبك لحالك: نكون معك خطوة بخطوة نجهزك لها.\n\nكل هذا وأنت تستلم تقارير أول بأول توضح لك بالضبط وين وصلنا معاك.\n\n💚 وإذا فُصلت من وظيفتك مؤخرًا وتمر بضائقة بسببها، وأنت مسؤول عن بيت وما عندك دخل حاليًا — أرسل لنا ما يثبت وضعك ونفعّل لك ٢٢ يوم مجانًا فورًا، فمن فرّج عن مسلم كربة فرّج الله عنه كربة من كرب يوم القيامة، وهذا كل اللي يهمنا.\n\nللبدء معنا، تواصل عبر واتساب على: +966544161255';
  }
} else if (!step) {
  route = 'plain';
  replyText = '🎉 تم تفعيل اشتراكك، الله يوفقك! أرسل الآن سيرتك الذاتية — ملف PDF أو صورة واضحة لها — لنبدأ العمل عليها.';
  patch.step = 'awaiting_cv';
} else if (step === 'awaiting_cv') {
  if (v.hasAttachment && !v.attachmentUnsupported) {
    route = 'analyze_cv';
  } else if (v.attachmentUnsupported) {
    route = 'plain';
    replyText = 'الصيغة غير مدعومة 🙏 أرسل سيرتك الذاتية كملف PDF أو صورة واضحة.';
  } else {
    route = 'plain';
    replyText = 'لسة وصلت! 📄 أرسل سيرتك الذاتية كملف PDF أو صورة واضحة لها عشان نبدأ العمل:';
  }
