  titles.forEach(function(t, i){ msg += (i+1) + '. ' + t + '\n'; });
  msg += '\nاختر واحد: (1) القائمة كافية وأقدّم بها — (2) أضيف مجال آخر (بحد أقصى ' + MAX_FIELDS + ') — (3) احذف مجال غير مناسب، إما بالضغط على الزر أو بكتابة الرقم:';
  return msg;
