function tryRepairJson(text) {
  try { return JSON.parse(text); } catch (e) {}
  let inStr = false, esc = false;
  let lastGoodIndex = -1;
  const depth = [];
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inStr) {
      if (esc) { esc = false; }
      else if (c === '\\') { esc = true; }
      else if (c === '"') { inStr = false; }
      continue;
    }
    if (c === '"') { inStr = true; continue; }
    if (c === '{' || c === '[') depth.push(c);
    else if (c === '}' || c === ']') {
      depth.pop();
      if (depth.length > 0) lastGoodIndex = i;
    }
  }
  if (lastGoodIndex === -1) return null;
  let truncated = text.slice(0, lastGoodIndex + 1);
  const stack = [];
  inStr = false; esc = false;
  for (let i = 0; i < truncated.length; i++) {
    const c = truncated[i];
    if (inStr) {
      if (esc) { esc = false; }
      else if (c === '\\') { esc = true; }
      else if (c === '"') { inStr = false; }
      continue;
    }
    if (c === '"') { inStr = true; continue; }
    if (c === '{' || c === '[') stack.push(c);
    else if (c === '}' || c === ']') stack.pop();
  }
  truncated = truncated.replace(/,\s*$/, '');
  const closer = stack.reverse().map(function(ch) { return ch === '{' ? '}' : ']'; }).join('');
  try { return JSON.parse(truncated + closer); } catch (e) { return null; }
}

