    text = '📋 حالة اشتراكك\n\n✅ اشتراكك فعّال حاليًا، الله يوفقك.\n\n📅 بدأ بتاريخ: ' + fmt(row.subscriptionStartDate) + '\n📅 ينتهي بتاريخ: ' + fmt(row.subscriptionEndDate) + '\n\nإذا احتجت أي شي اضغط زر "📞 تواصل معنا" من القائمة.';
  } else {
    text = '📋 حالة اشتراكك\n\nانتهى اشتراكك بتاريخ ' + fmt(row.subscriptionEndDate) + '.\n\nإذا تحب ترجع وتستفيد من الخدمة، اضغط زر "📞 تواصل معنا" من القائمة.';
  }
}

return { json: { chatId: chatId, replyText: text } };

const j = $json;
const CATEGORY_LABELS = {
  complaint: '📝 ملاحظة أو شكوى',
  support: '🎧 طلب دعم',
  heart: '💌 رسالة من قلب لقلب'
};
const label = CATEGORY_LABELS[j.contactCategory] || j.contactCategory || 'غير محدد';
const customerName = j.customerName || 'غير معروف';
const phone = j.verifiedPhone || 'غير متوفر';
const chatId = j.chatId;
const msg = j.contactMessageText || '';

const adminText = '📨 رسالة جديدة من عميل\n\n👤 الاسم: ' + customerName + '\n📱 الجوال: ' + phone + '\n🏷️ النوع: ' + label + '\n\n💬 الرسالة:\n' + msg;
const confirmText = 'تم استلام رسالتك ✅ وصلت لفريق مسار، وبنرد عليك أو نتواصل معك قريبًا بإذن الله.\n\nنقدّر تواصلك معنا 🤍';

return { json: { chatId: chatId, adminText: adminText, confirmText: confirmText } };

